function get_draft_ids() {
    $key = 'my_plugin_draft_ids';
    $cached = <em>wp_cache_get</em>( $key );

    if ( false !== $cached ) {
        return $cached;
    }

    $results = $wpdb->get_col(
        "SELECT ID FROM $wpdb->posts
            WHERE post_status = 'draft'"
    );

    <em>wp_cache_set</em>( $key, $results );

    return $results;
}


function get_draft_ids() {
    $results = $wpdb->get_col(
        "SELECT ID FROM $wpdb->posts
            WHERE post_status = 'draft'"
    );

    return $results;
}
